const channel=('BroadcastChannel' in window)?new BroadcastChannel('gmm-v2-sync'):null;const signal=()=>channel?.postMessage('changed');
let state={songs:[],productions:[],assets:[],publications:[],history:[],settings:[],view:'dashboard',selected:new Set(),search:'',decade:'',sort:'relevance',layout:'list',filters:{},advanced:false,page:0,favorites:false,unused:false,active:null,pubLayout:'list',pubPlatform:'',archiveQuery:'',archiveDecade:'',archivePlatform:'',archiveStatus:'',repertoire:'',cover:null,coverProd:'',bg:null};
