const input=(name,label,value='',type='text',more='')=>`<label class="field">${label}<input name="${name}" id="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
const empty=text=>`<div class="empty">${text}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5500);}
async function refresh(){for(const s of ['songs','productions','assets','publications','history','settings','reservations'])state[s]=await all(s);state.selected=new Set((state.reservations||[]).filter(r=>r.status==='reserved').map(r=>r.songId));state.searchIndex=createSearchIndex(state.songs);state.songIndex=new Map(state.songs.map(s=>[s.id,s]));state.assetIndex=new Map();state.pubIndex=new Map();state.canonIndex=new Map();for(const a of state.assets){const list=state.assetIndex.get(a.productionId)||[];list.push(a);state.assetIndex.set(a.productionId,list);}for(const list of state.assetIndex.values())list.sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||''))||a.version-b.version);for(const p of state.publications){const list=state.pubIndex.get(p.productionId)||[];list.push(p);state.pubIndex.set(p.productionId,list);}for(const p of state.productions){const key=canonicalKey(songOf(p)),list=state.canonIndex.get(key)||[];list.push(p);state.canonIndex.set(key,list);}}
function showDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').setAttribute('aria-label',$('#dialog-body h2')?.textContent||'Detalhes');if(!$('#dialog').open)$('#dialog').showModal();}
$('#close-dialog').onclick=()=>$('#dialog').close();
async function route(view,id){if(state.view==='covers'&&state.cover){clearTimeout(coverTimer);await saveCoverDraft();}await refresh();state.view=view;state.active=id||null;location.hash=view+(id?'/'+id:'');await render();}
function mediaURL(a){const url=URL.createObjectURL(a.blob);objectURLs.push(url);return url;}
async function render(){const coverTrash=$('#cover-trash'),keepCoverTrash=state.view==='production'&&coverTrash?.dataset.productionId===state.active&&coverTrash.open;const token=++renderToken;for(const u of objectURLs)URL.revokeObjectURL(u);objectURLs=[];$('#page-title').textContent=TITLES[state.view]||'Golden Music Memories';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#store-status').textContent='Salvo neste navegador';const views={dashboard:()=>operationsSummary()+dashboard(),catalog:catalog,covers:covers,production:production,publications:publications,archive:archive,backup:backup,settings:config,operations:operationsView};$('#main').innerHTML=(views[state.view]||dashboard)();if(keepCoverTrash&&$('#cover-trash'))$('#cover-trash').open=true;if(token!==renderToken)return;bind();if(state.view==='catalog'){for(const id of ['decade-filter','sort-filter']){const field=$('#'+id),previous=field?.onchange;if(field)field.onchange=event=>{previous?.(event);put('settings',{id:'catalogRankingFilter',rankingList:state.filters.rankingList||'',rankingLimit:state.filters.rankingLimit||'30',decade:state.decade,sort:state.sort}).catch(fail);};}}mountDestinationPickers($('#main'));if(state.view==='covers')await paint();if(state.view==='backup'||state.view==='settings')storageInfo();if(state.view==='backup')mountStorage();if(state.view==='publications')await mountRepostHistory(id=>actions['edit-pub-id']({dataset:{id}}));const hooks={showDialog,mediaURL,refresh,render,toast,settings:()=>route('settings'),manualPost:async m=>{await refresh();const p=state.productions.find(p=>p.id===m.productionId);if(!p)throw Error('Abra/sincronize a produção neste navegador antes de registrar.');return publicationDialog(p.id,m.platforms[0],null,null,m);}};bindService(hooks);if(['operations','dashboard'].includes(state.view))mountOperations(hooks,state.view==='operations');}
function dashboard(){const d=today(),ps=state.productions.filter(p=>day(p.createdAt)===d),done=state.assets.filter(a=>['tiktok','youtube'].includes(a.role)&&day(a.createdAt)===d),finished=new Set(done.map(a=>a.productionId)),posted=state.publications.filter(p=>p.publishedAt?.slice(0,10)===d&&p.status==='published');const used=new Set(state.productions.map(p=>p.songId)),pref=settings();return `<p class="lead">Escolha seus clássicos, acompanhe cada etapa e preserve todas as versões.</p><div class="actions">${btn('go-catalog','Escolher músicas')}${btn('go-production','Retomar produção','','secondary')}${btn('go-backup','Exportar backup','','secondary')}</div><div class="stats"><div class="stat gold"><span>PRODUÇÕES INICIADAS HOJE</span><strong>${ps.length} <small>/ ${pref.dailyProduction}</small></strong><progress value="${Math.min(ps.length,pref.dailyProduction)}" max="${pref.dailyProduction}"></progress></div><div class="stat"><span>PRODUÇÕES FINALIZADAS HOJE</span><strong>${finished.size}</strong><small>${done.length} arquivos finais importados</small></div><div class="stat"><span>PUBLICAÇÕES REGISTRADAS HOJE</span><strong>${posted.length}</strong><small>TikTok ${posted.filter(p=>p.platform==='tiktok').length}/${pref.dailyTikTok} · YouTube ${posted.filter(p=>p.platform==='youtube').length}/${pref.dailyYouTube}</small></div><div class="stat"><span>MÚSICAS DISPONÍVEIS</span><strong>${state.songs.filter(s=>usageOf(s)==='available'||usageOf(s)==='cancelled').length}</strong><small>${state.selected.size} reservadas para produção</small></div></div><div class="columns"><section class="panel"><h2>Produção em andamento</h2>${state.productions.filter(p=>p.status<6&&!p.cancelled).slice(-5).reverse().map(p=>`<p>${btn('open-production',esc(songOf(p)?.title),'data-id="'+p.id+'"','link')} <small>· ${STATUS[p.status]} · V${p.version}</small></p>`).join('')||'<p class="muted">Inicie pelo catálogo. Uma produção pode ser salva e concluída individualmente.</p>'}</section><section class="panel"><h2>Seu acervo, em números</h2><p>${state.assets.filter(a=>a.role==='cover'&&!a.trashedAt).length} capas aprovadas · ${state.assets.filter(a=>['tiktok','youtube'].includes(a.role)).length} vídeos finais</p><p>${state.productions.filter(p=>p.status===7).length} versões arquivadas · ${state.publications.filter(p=>p.status==='planned').length} publicações planejadas</p><p class="note">${state.songs.filter(s=>s.validation==='curated').length} músicas revisadas editorialmente. ${state.songs.filter(s=>s.validation==='metadata_imported').length} registros importados com referência de metadados.</p></section></div><details class="panel"><summary>Desempenho registrado</summary><div class="metrics">${['views','likes','comments','shares'].map((k,i)=>`<div><small>${['Visualizações','Curtidas','Comentários','Compartilhamentos'][i]}</small><h2>${state.publications.reduce((n,p)=>n+Number(p.metrics?.[k]||0),0).toLocaleString('pt-BR')}</h2></div>`).join('')}</div><small>Somente métricas preenchidas pelo operador. Nenhuma coleta automática conectada.</small></details>`;}
function filteredSongs(){return filteredCatalog(state,{usageOf,assetsOf,pubsOf,canonicalKey});}
function catalog(){return catalogView(state,{esc,btn,input,select,options,usageOf,USAGE,filteredSongs,settings});}
function production(){if(!state.active){return `<div class="actions">${btn('collections','Preparar coletânea','','secondary')}</div><p class="lead">Retome qualquer etapa. Cada versão mantém seus próprios arquivos e publicações.</p>${state.productions.length?`<div class="grid">${state.productions.slice().reverse().map(p=>{const s=songOf(p);return `<article class="production-card"><span class="tag">V${p.version} · ${STATUS[p.status]}</span><h3>${esc(s.title)}</h3><p>${esc(s.artist)} · ${p.versionYear||s.year}</p><small>${assetsOf(p.id).length} arquivos · ${pubsOf(p.id).length} publicações</small><div class="actions">${btn('open-production','Abrir produção','data-id="'+p.id+'"','small')}</div></article>`;}).join('')}</div>`:empty('Ainda não há produções. Escolha uma música no catálogo.')}`;}
const p=state.productions.find(x=>x.id===state.active);if(!p)return empty('Produção não encontrada.');const s=songOf(p),files=assetsOf(p.id);return `<div class="breadcrumbs">${btn('go-production','← Todas as produções','','link')} / ${esc(p.id.slice(0,8))} · V${p.version}</div><div class="section-head"><div><h2>${esc(s.title)}</h2><p class="muted">${esc(s.artist)} · ${s.year} <small>(${esc(s.yearMeaning||'ano informado')})</small></p></div><div class="actions">${btn('cover-production','Criar capa','data-id="'+p.id+'"')}${btn('new-version','Criar nova versão','data-id="'+p.id+'"','secondary')}${btn('cancel-production','Cancelar / liberar','data-id="'+p.id+'"','secondary')}</div></div><div class="steps">${['Escolha','Capa','Mídias','Edição','Revisão','Publicação','Acervo'].map((v,i)=>`<span class="${i<=Math.min(p.status,6)?'on':''}">${i+1}. ${v}</span>`).join('')}</div><form id="production-form" class="panel"><div class="form-grid">${select('stage','Etapa',Object.fromEntries(STATUS.map((v,i)=>[i,v])),p.status)}${input('versionYear','Ano da versão usada na capa',p.versionYear||s.year,'number','min="1960" max="2100" required')}${input('plannedDate','Data de produção planejada',p.plannedDate||today(),'date')}<label class="field">Observações / roteiro<textarea name="notes" id="notes">${esc(p.notes||'')}</textarea></label></div><small>As alterações são salvas automaticamente neste navegador.</small><div class="actions">${btn('save-production','Salvar agora','','small')}${btn('export-production','Exportar pacote para edição','data-id="'+p.id+'"','secondary small')}${btn('folder-manifest','Ver estrutura de pastas','data-id="'+p.id+'"','secondary small')}</div></form><section class="panel"><div class="section-head"><h2>Materiais e arquivos</h2>${btn('assemble-video','Montar vídeo','data-id="'+p.id+'"')}${btn('replace-clip','Substituir clipe','data-id="'+p.id+'"','secondary small')}${btn('source-import','Importar link / materiais locais','data-id="'+p.id+'"','secondary small')}${btn('approve-review','Registrar revisão','data-id="'+p.id+'"','secondary small')} </div><p class="muted">Anexos abaixo ficam neste navegador. Clipes guardados no serviço local aparecem em Montar vídeo ou Substituir clipe.</p><label class="field">Tipo do material<select id="asset-role">${options({cover:'Capa',audio:'Áudio',clip:'Clipe',image:'Imagem complementar',project:'Projeto CapCut / auxiliar',tiktok:'Vídeo final TikTok',youtube:'Vídeo final YouTube',text:'Legenda / descrição'},'image')}</select></label><div class="dropzone" id="dropzone"><label>Arraste arquivos aqui ou <input id="asset-upload" type="file" multiple></label><small>Arquivos no navegador: até 500 MB. Para vídeos maiores, use Acervo e programação e o cache do serviço local.</small></div>${files.map(assetRow).join('')||empty('Nenhum arquivo anexado. As novas versões preservam os arquivos anteriores.')}<details id="cover-trash" data-production-id="${esc(p.id)}"><summary>Capas na lixeira (recuperáveis)</summary><p>Bytes preservados neste navegador; continuam ocupando espaço. Restaurar mantém IDs e referências.</p>${state.assets.filter(a=>a.productionId===p.id&&a.role==='cover'&&a.trashedAt).map(assetRow).join('')||'<p>Nenhuma capa na lixeira.</p>'}</details></section><section class="panel"><h2>Preparar publicações</h2><p>Escolha plataforma e formato. Textos e registros são independentes; um MP4 compatível pode ser reutilizado.</p>${destinationPicker({id:'prepare-destination',context:'posting',productionId:p.id})}<details><summary>YouTube Music</summary><p>Distribuição musical exige áudio, metadados, direitos e distribuidor/parceiro. Upload de vídeo não garante entrada no catálogo do YouTube Music. Upload pessoal de áudio é privado para quem enviou, não distribui música ao público. Decisão de distribuição pendente.</p></details>${pubsOf(p.id).map(pub=>`<p>${esc(POST_DESTINATIONS[destinationOf(pub)]?.label||pub.platform)} · ${esc(publicationStatusLabel(pub.status))} · ${esc(pub.title)}</p>`).join('')}</section>`;}
function assetRow(a){const p=state.productions.find(p=>p.id===a.productionId),s=p&&songOf(p),displayName=s?readableName(s.artist,s.title,a.role,a.version,a.name.split('.').pop()):a.name;let preview='';const url=mediaURL(a);if(a.type.startsWith('image/'))preview=`<img src="${url}" alt="${esc(a.originalName||a.name)}">`;if(a.type.startsWith('video/'))preview=`<video controls preload="metadata" src="${url}"></video>`;if(a.type.startsWith('audio/'))preview=`<audio controls preload="metadata" src="${url}"></audio>`;return `<div class="asset">${preview}<div class="info"><p><b>${esc(displayName)}</b></p><small>Original: ${esc(a.originalName||a.name)}<br>${esc(a.role==='license'?'Documento preservado':ASSET_FOLDERS[a.role]||a.role)} · V${a.version} · ${(a.size/1048576).toFixed(2)} MB<br>${new Date(a.createdAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></div>${!a.trashedAt&&a.coverConfig?btn('recover-cover','Editar esta versão','data-id="'+a.id+'"','secondary small'):''}${btn('download-asset','Baixar','data-id="'+a.id+'"','secondary small')}${a.role==='cover'?btn(a.trashedAt?'restore-cover':'trash-cover',a.trashedAt?'Restaurar capa':'Excluir capa','data-id="'+a.id+'"','secondary small'):''}</div>`;}
function covers(){if(!state.cover){const draft=state.settings.find(s=>s.id==='coverDraft');state.cover=draft?.config||{title:'Take On Me',artist:'a-ha',year:'1985',style:'cassette',format:'vertical',font:104,x:.085,y:.23,text:'#f8f0df',accent:'#edc283',safe:false};state.coverProd=draft?.productionId||state.coverProd;}const c=state.cover;return `<p class="lead">Templates locais sem custo de API. Salve cada arte aprovada como uma nova versão da produção. Os fundos são verticais 9:16; no formato horizontal o fundo sofre recorte proporcional, sem esticar. Use um fundo horizontal próprio para preservar sua composição inteira.</p><div class="template-family" aria-label="Família oficial de templates">${Object.entries(TEMPLATES).map(([id,t])=>`<button type="button" data-action="select-template" data-id="${id}" aria-pressed="${c.style===id}" class="template-card ${c.style===id?'selected':''}"><img src="${t.asset}" alt="" loading="lazy"><span>${esc(t.name)}</span></button>`).join('')}</div><div class="editor"><section class="panel"><form id="cover-form">${select('cover-production','Produção associada',{'':'Escolha uma produção',...Object.fromEntries(state.productions.map(p=>[p.id,songOf(p).title+' · V'+p.version]))},state.coverProd)}${input('cover-title','Nome da música',c.title)}${input('cover-artist','Artista',c.artist)}<div class="form-grid">${input('cover-year','Ano da versão',c.year)}${select('cover-style','Estilo',Object.fromEntries(Object.entries(STYLES).map(([k,v])=>[k,v[0]])),c.style)}${select('cover-format','Formato',{vertical:'TikTok / Shorts · 1080×1920',horizontal:'YouTube · 1280×720'},c.format)}${select('cover-family','Tipografia',{Arial:'Arial','Georgia':'Georgia','Verdana':'Verdana'},c.family||'Arial')}${input('cover-text','Cor do texto',c.text,'color')}${input('cover-accent','Cor de destaque',c.accent,'color')}${input('cover-font','Tamanho do título',c.font,'range','min="40" max="160"')}${input('cover-x','Posição horizontal',c.x,'range','min="0.04" max="0.35" step="0.01"')}${input('cover-y','Posição vertical',c.y,'range','min="0.15" max="0.55" step="0.01"')}</div><label class="field">Imagem própria de fundo<input id="cover-background" type="file" accept="image/*"></label><label><input id="cover-safe" type="checkbox" ${c.safe?'checked':''}> Mostrar margens de referência na prévia</label><p class="muted"><small>As margens não são exportadas. Nos Shorts, a plataforma pode permitir apenas selecionar um quadro do vídeo.</small></p></form><div class="actions">${btn('variation','Outra variação','','secondary')}${btn('download-cover','Baixar PNG')}${btn('download-jpg','Baixar JPG','','secondary')}${btn('approve-cover','Aprovar e guardar','','secondary')}</div><p id="cover-feedback" class="muted"></p></section><div class="preview"><canvas id="cover-canvas" width="1080" height="1920" aria-label="Prévia da capa"></canvas><small>Produção independente · identidade preservada</small></div></div>`;}
function publications(){const pubs=state.publications.filter(p=>!state.pubPlatform||p.platform===state.pubPlatform);let body='';if(state.pubLayout==='kanban'){body=`<div class="kanban">${STATUS.map((label,i)=>`<section class="lane"><h3>${label}</h3>${state.productions.filter(p=>p.status===i).map(p=>`<article><b>${esc(songOf(p).title)}</b><p>V${p.version}</p>${pubsOf(p.id).filter(pub=>!state.pubPlatform||pub.platform===state.pubPlatform).map(pub=>`<small>${pub.platform} · ${esc(pub.plannedAt?.slice(0,10)||'Sem data')}</small><br>`).join('')}${btn('open-production','Abrir','data-id="'+p.id+'"','small secondary')}</article>`).join('')||'<small>Sem produções</small>'}</section>`).join('')}</div>`;}else if(state.pubLayout==='calendar'){const month=state.calendarMonth||today().slice(0,7);const [year,m]=month.split('-').map(Number),days=new Date(year,m,0).getDate();body=`${input('calendar-month','Mês',month,'month')}<div class="calendar">${Array.from({length:days},(_,i)=>{const day=month+'-'+String(i+1).padStart(2,'0');return `<div class="day"><b>${i+1}</b>${pubs.filter(p=>(p.plannedAt||'').slice(0,10)===day).map(p=>`<article>${btn('edit-pub-id',esc(p.title),'data-id="'+p.id+'"','link')}<br>${esc(POST_DESTINATIONS[destinationOf(p)]?.label||p.platform)} · ${esc(publicationStatusLabel(p.status))}</article>`).join('')}</div>`;}).join('')}</div>`;}else body=pubs.length?`<div class="table-wrap"><table><thead><tr><th>Música / plataforma</th><th>Planejada</th><th>Situação / arquivo</th><th>Ações</th></tr></thead><tbody>${pubs.map(p=>`<tr><td><b>${esc(p.title)}</b><br>${esc(POST_DESTINATIONS[destinationOf(p)]?.label||p.platform)}</td><td>${esc(p.plannedAt?.replace('T',' ')||'Sem data')}</td><td>${esc(publicationStatusLabel(p.status))}<br><small>${p.finalAssetId||p.localRenderAssetId||p.serviceMediaId?'Vídeo associado':'Sem vídeo final'}</small></td><td><div class="actions">${btn('edit-pub-id','Editar','data-id="'+p.id+'"','small')}${btn('copy-publication','Copiar descrição','data-id="'+p.id+'"','secondary small')}${safeURL(p.url)?`<a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">Abrir postagem</a>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Prepare uma publicação dentro de uma produção.');return `${repostHistoryPanel()}${servicePublicationsPanel(pubs.filter(p=>['youtube','tiktok'].includes(p.platform)&&['youtube','tiktok'].includes(destinationOf(p))))}${deliveryPanel(pubs.filter(p=>['youtube','tiktok'].includes(p.platform)&&['youtube','tiktok'].includes(destinationOf(p))))}<p class="lead">Planejamento e registro manual assistido. Agendar aqui não envia conteúdo às plataformas.</p><div class="filters"><select id="pub-platform" aria-label="Plataforma">${options({'':'Todas as plataformas',...PLATFORMS},state.pubPlatform)}</select>${btn('pub-list','Lista','','secondary')}${btn('pub-kanban','Kanban','','secondary')}${btn('pub-calendar','Calendário','','secondary')}</div>${body}`;}
function archive(){let items=state.assets.filter(a=>['tiktok','youtube'].includes(a.role));items=items.filter(a=>{const p=state.productions.find(p=>p.id===a.productionId),s=songOf(p);return normalize(`${s.title} ${s.artist} ${a.createdAt}`).includes(normalize(state.archiveQuery))&&(!state.archiveDecade||s.decade==state.archiveDecade)&&(!state.archivePlatform||a.role===state.archivePlatform)&&(!state.archiveStatus||(state.archiveStatus==='unpublished'?!pubsOf(p.id).some(pub=>pub.status==='published'):pubsOf(p.id).some(pub=>pub.status==='published')));});return `<p class="lead">Vídeos finais importados e suas versões. Nenhum arquivo anterior é substituído ao criar uma nova versão.</p><div class="filters"><input type="search" id="archive-search" value="${esc(state.archiveQuery)}" placeholder="Música, artista ou data" aria-label="Pesquisar acervo"><select id="archive-decade" aria-label="Década">${options({'':'Todas as décadas',1960:'Anos 60',1970:'Anos 70',1980:'Anos 80',1990:'Anos 90',2000:'Anos 2000'},state.archiveDecade)}</select><select id="archive-platform" aria-label="Plataforma">${options({'':'Todas as plataformas',tiktok:'TikTok',youtube:'YouTube'},state.archivePlatform)}</select><select id="archive-status" aria-label="Publicação">${options({'':'Todas as situações',published:'Publicados',unpublished:'Não publicados'},state.archiveStatus)}</select></div>${items.length?items.map(a=>{const p=state.productions.find(p=>p.id===a.productionId),s=songOf(p);return `<section class="panel"><div class="section-head"><h3>${esc(s.title)} — ${esc(s.artist)} · V${p.version}</h3><div class="actions">${btn('open-production','Ver produção','data-id="'+p.id+'"','secondary small')}${btn('new-version','Criar nova versão','data-id="'+p.id+'"','small')}</div></div>${assetRow(a)}</section>`;}).join(''):empty('Nenhum vídeo final encontrado. Importe um MP4 no Estúdio de produção.')}`;}
function backup(){return `<p class="lead">Leve registros e arquivos juntos para outro computador. A restauração verifica referências e integridade dos arquivos antes de substituir os dados locais.</p><div class="columns"><section class="panel"><h2>Backup deste navegador</h2><p>Inclui catálogo, produções, anexos deste perfil, publicações, métricas e histórico, com verificação SHA-256. Não inclui SQLite, fontes e renders do serviço.</p>${btn('export-backup','Baixar backup ZIP')}<p class="note">Copie esse ZIP para seu Google Drive e para um armazenamento externo. Não há envio automático.</p></section><section class="panel"><h2>Restaurar backup</h2><p>Escolha um backup exportado pelo painel. O conteúdo atual só será substituído depois da validação e confirmação.</p><input type="file" id="restore-input" accept=".zip" aria-label="Selecionar backup ZIP"><p id="restore-feedback"></p></section></div>${storagePanel()}<section class="panel"><h2>Google Drive · estrutura organizada</h2><p>O pacote de cada produção usa pastas padronizadas para capas, áudios, clipes, CapCut, finais e documentos.</p>${btn('drive-structure','Baixar estrutura de pastas','','secondary')}<p class="muted">Integração OAuth não configurada. Exporte os pacotes e faça upload manual no Drive.</p><div id="storage-info"></div></section><section class="panel"><h2>Exportar controles</h2>${btn('export-records','Baixar catálogo e controle JSON','','secondary')} <small>Este arquivo contém os registros; para incluir anexos deste perfil, use o backup ZIP do navegador.</small></section>`;}
function config(){const p=settings();return `${serviceConfigurationPanel()}<p class="lead">As funções essenciais operam sem APIs pagas. Nenhuma credencial administrativa é solicitada ou armazenada neste painel.</p><form id="settings-form" class="panel"><h2>Rotina de produção</h2><div class="form-grid">${input('channel','Nome do canal',p.channel)}${input('dailyProduction','Meta diária de produções',p.dailyProduction,'number','min="1"')}${input('dailyTikTok','Meta diária TikTok',p.dailyTikTok,'number','min="0"')}${input('dailyYouTube','Meta diária YouTube',p.dailyYouTube,'number','min="0"')}${input('dailyArchive','Meta diária de arquivamentos',p.dailyArchive??5,'number','min="0"')}${input('dailyReuse','Meta diária de novas versões',p.dailyReuse??0,'number','min="0"')}${select('quality','Formato de imagem padrão',{'image/png':'PNG · sem perdas','image/jpeg':'JPG · qualidade 92%'},p.quality)}</div><button type="submit">Salvar configurações</button></form><section class="panel"><h2>Armazenamento e integrações</h2><p><span class="tag">Operacional</span> Banco local IndexedDB · arquivos neste navegador · backup ZIP</p><p><span class="tag">Fluxo externo assistido</span> Canva Pro: exporte as músicas selecionadas em CSV para Criação em lote e devolva as artes à produção.</p><p><span class="tag warn">Pendente</span> Google Drive: requer configuração OAuth e homologação.</p><p><span class="tag warn">Pendente</span> Operação local: banco privado no computador. Oracle, Colab e migração para Supabase fora deste fluxo.</p><p><span class="tag warn">Pendente</span> Provedor de imagens por API: requer backend, credenciais e aprovação de custo. A família oficial de sete templates e os estilos adicionais funcionam sem API.</p><p><span class="tag warn">Manual</span> CapCut, TikTok e YouTube: pacotes e metadados; sem API de publicação conectada.</p><div id="storage-info"></div>${btn('persist-storage','Solicitar armazenamento persistente','','secondary')}</section><section class="panel"><h2>Metadados e privacidade</h2><p>${state.songs.length} músicas cadastradas · ${state.songs.filter(s=>s.validation==='curated').length} revisadas editorialmente.</p><p>Dados importados do MusicBrainz são comunitários e mantêm referência da gravação. O ano informado não garante a data original da composição.</p><p>Arquivos enviados ficam no navegador e não são enviados ao repositório público. Use o backup ZIP para levar seus dados a outro computador; não há sincronização automática.</p></section>`;}
async function storageInfo(){try{const e=await navigator.storage.estimate();if($('#storage-info'))$('#storage-info').textContent=`Navegador nesta origem (inclui cache): ${(e.usage/1048576).toFixed(1)} MB · cota estimada: ${(e.quota/1073741824).toFixed(1)} GB. Faça backups regulares.`;}catch{}}
async function createProduction(songId,previous){const p={id:uid(),songId,version:previous?previous.version+1:1,parentId:previous?.id||null,status:0,createdAt:now(),updatedAt:now(),plannedDate:today(),versionYear:previous?.versionYear||state.songs.find(s=>s.id===songId).year,rights:{recording:'pending',composition:'pending',visual:'pending',tiktok:'pending',youtube:'pending',commercial:'pending'},notes:previous?.notes||''};const versions=state.productions.filter(x=>x.songId===songId);p.version=Math.max(0,...versions.map(x=>x.version))+1;await atomicProduction(state.songs.find(s=>s.id===songId),p,!!previous);signal();if(previous){for(const a of assetsOf(previous.id)){const {id,...rest}=a;await put('assets',{...rest,id:uid(),productionId:p.id,rights:'pending',inheritedFrom:id,createdAt:now()});}}await audit('production_created',p.id,previous?'Nova versão de '+previous.id:'');await refresh();return p;}
async function uploadFiles(files,role,pid=state.active){uploading++;toast('Salvando arquivos…');const toggle=()=>document.querySelectorAll('[data-action="approve-review"],[data-action="new-version"],[data-action="export-production"],#asset-upload').forEach(b=>b.disabled=uploading>0);toggle();try{return await processUploads(files,role,pid);}finally{uploading--;toggle();}}
async function processUploads(files,role,pid=state.active){if(!pid)throw Error('Escolha uma produção.');const p=state.productions.find(x=>x.id===pid);for(const file of files){if(file.size>500*1048576)throw Error('Arquivo acima de 500 MB. Use um arquivo menor ou armazenamento externo.');if(['tiktok','youtube'].includes(role)&&!(/\.mp4$/i.test(file.name)&&file.type.startsWith('video/')))throw Error('Para versão final, selecione um vídeo MP4.');const hash=await digest(file);if(state.assets.some(a=>a.productionId===pid&&a.hash===hash&&a.role===role)){toast(state.assets.some(a=>a.productionId===pid&&a.hash===hash&&a.role===role&&a.trashedAt)?'Arquivo idêntico está na lixeira recuperável; restaure a capa existente.':'Arquivo idêntico já existe nesta produção.');continue;}const version=state.assets.filter(a=>a.productionId===pid&&a.role===role).length+1,id=uid(),ext=file.name.split('.').pop().replace(/[^a-zA-Z0-9]/g,'').slice(0,10),name=readableName(songOf(p).artist,songOf(p).title,role,version,ext);await put('assets',{id,productionId:pid,songId:p.songId,role,version,name,originalName:file.name,type:file.type||'application/octet-stream',size:file.size,hash,blob:file,rights:'pending',createdAt:now()});await refresh();}const latest=(await all('productions')).find(x=>x.id===pid);latest.approval=null;await put('productions',latest);await audit('media_imported',pid,role);}
async function paint(){const canvas=$('#cover-canvas');if(!canvas)return;const cfg=state.cover;let bg=state.bg;if(!bg&&cfg.backgroundAssetId){const a=state.assets.find(a=>a.id===cfg.backgroundAssetId);if(a)bg=mediaURL(a);}if(!bg)bg=templateBackground(cfg.style);await drawCover(canvas,cfg,bg);}
function readCover(){const map={title:'cover-title',artist:'cover-artist',year:'cover-year',style:'cover-style',format:'cover-format',family:'cover-family',text:'cover-text',accent:'cover-accent',font:'cover-font',x:'cover-x',y:'cover-y'};for(const [k,v]of Object.entries(map))if($('#'+v))state.cover[k]=$('#'+v).value;state.cover.safe=$('#cover-safe').checked;state.coverProd=$('#cover-production').value;}
async function coverBlob(type='image/png'){const canvas=document.createElement('canvas');const c={...state.cover,safe:false};let bg=state.bg;if(!bg&&c.backgroundAssetId){const a=state.assets.find(a=>a.id===c.backgroundAssetId);if(a)bg=mediaURL(a);}if(!bg)bg=templateBackground(c.style);await drawCover(canvas,c,bg);return new Promise(r=>canvas.toBlob(r,type,.92));}
async function saveProduction(){const p=state.productions.find(p=>p.id===state.active);if(!p||!$('#production-form'))return;const previous=p.status;p.status=Number($('#stage').value);if(p.status===5&&!p.approval){p.status=previous;$('#stage').value=String(previous);throw Error('Registre a revisão da capa e do vídeo antes de marcar Pronto para publicar.');}p.notes=$('#notes').value;p.plannedDate=$('#plannedDate').value;p.versionYear=Number($('#versionYear').value);if(!p.versionYear||p.versionYear<1960||p.versionYear>2100)return;p.updatedAt=now();await put('productions',p);if(previous!==p.status)await audit('production_stage_changed',p.id,STATUS[p.status]);$('#store-status').textContent='Alterações salvas';}
function bind(){bindCatalog();const rankingDetails=$('.catalog-ranking');if(rankingDetails)rankingDetails.ontoggle=()=>{state.rankingOpen=rankingDetails.open;};for(const id of ['ranking-list','ranking-limit'])if($('#'+id))$('#'+id).onchange=()=>guarded(async()=>{state.filters={...state.filters,rankingList:$('#ranking-list').value,rankingLimit:$('#ranking-limit').value};state.page=0;await put('settings',{id:'catalogRankingFilter',rankingList:state.filters.rankingList,rankingLimit:state.filters.rankingLimit,decade:state.decade,sort:state.sort});render();});for(const [id,key]of [['repertoire-filter','repertoire'],['decade-filter','decade'],['sort-filter','sort'],['pub-platform','pubPlatform'],['archive-decade','archiveDecade'],['archive-platform','archivePlatform'],['archive-status','archiveStatus'],['calendar-month','calendarMonth']])if($('#'+id))$('#'+id).onchange=e=>{state[key]=e.target.value;state.page=0;render();};for(const [id,key]of [['favorites-only','favorites'],['unused-only','unused']])if($('#'+id))$('#'+id).onchange=e=>{state[key]=e.target.checked;state.page=0;render();};document.querySelectorAll('[data-song-select]').forEach(c=>c.onchange=()=>{guarded(async()=>{const song=state.songs.find(s=>s.id===c.dataset.songSelect);if(c.checked)await reserveSongs([song]);else await releaseSong(song);await refresh();signal();render();});});if($('#archive-search'))$('#archive-search').onchange=e=>{state.archiveQuery=e.target.value;render();};if($('#production-form')){$('#production-form').onsubmit=e=>e.preventDefault();$('#production-form').oninput=()=>saveProduction().catch(fail);}if($('#asset-upload'))$('#asset-upload').onchange=async e=>{await guarded(async()=>{await uploadFiles(e.target.files,$('#asset-role').value);await refresh();render();toast('Materiais salvos.');});};if($('#dropzone')){const z=$('#dropzone');z.ondragover=e=>{e.preventDefault();z.classList.add('over');};z.ondragleave=()=>z.classList.remove('over');z.ondrop=e=>{e.preventDefault();guarded(async()=>{await uploadFiles(e.dataTransfer.files,$('#asset-role').value);await refresh();render();toast('Materiais salvos.');});};}if($('#cover-form')){$('#cover-form').onsubmit=e=>e.preventDefault();$('#cover-form').oninput=e=>{if(e.target.id==='cover-production')return;readCover();clearTimeout(coverTimer);coverTimer=setTimeout(()=>guarded(async()=>{await saveCoverDraft();await paint();}),180);};$('#cover-style').onchange=()=>guarded(()=>selectTemplate($('#cover-style').value));$('#cover-production').onchange=()=>guarded(()=>openProductionCover($('#cover-production').value));$('#cover-background').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f||!f.type.startsWith('image/'))throw Error('Escolha uma imagem.');if(f.size>20*1048576)throw Error('Imagem acima de 20 MB.');if(!state.coverProd)throw Error('Associe uma produção para preservar o fundo enviado.');await uploadFiles([f],'background',state.coverProd);const a=assetsOf(state.coverProd).filter(a=>a.role==='background').at(-1);state.cover.backgroundAssetId=a.id;state.bg=null;await saveCoverDraft();await paint();toast('Fundo salvo na produção.');});}if($('#restore-input'))$('#restore-input').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f)return;$('#restore-feedback').textContent='Validando arquivos e referências…';const data=await readBackup(f);if(!confirm(`Backup válido: ${data.tables.songs.length} músicas e ${data.tables.assets.length} arquivos. Substituir TODOS os dados deste navegador? Faça um backup antes se necessário.`)){$('#restore-feedback').textContent='Restauração cancelada; dados preservados.';return;}await restoreBackup(data);await refresh();const rankingFilter=state.settings.find(s=>s.id==='catalogRankingFilter');if(rankingFilter){state.filters={...state.filters,rankingList:rankingFilter.rankingList||'',rankingLimit:rankingFilter.rankingLimit||'30'};state.decade=rankingFilter.decade||'';state.sort=rankingFilter.sort||'relevance';}state.selected=new Set();state.cover=null;state.active=null;await route('dashboard');toast('Backup restaurado e integridade verificada.');});if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const f=new FormData(e.target),v={...settings()};for(const [k,val]of f){if(k.startsWith('daily')){const n=Number(val);if(!Number.isSafeInteger(n)||n<(k==='dailyProduction'?1:0))throw Error('As metas devem ser números inteiros válidos, sem valores negativos.');v[k]=n;}else v[k]=val;}await put('settings',v);await refresh();toast('Configurações salvas.');});};}
function fail(e){console.error(e);toast(e?.name==='QuotaExceededError'?'Sem espaço no navegador. Exporte um backup e libere espaço antes de continuar.':e.message||'Não foi possível concluir a operação.');}
async function guarded(fn){try{await fn();}catch(e){fail(e);}}
const actions={};
for(const name of ['catalog','production','backup','covers','archive','publications','settings','dashboard'])actions['go-'+name]=()=>route(name);
actions['toggle-layout']=()=>{state.layout=state.layout==='cards'?'list':'cards';render();};
actions['favorite']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);s.favorite=!s.favorite;await put('songs',s);await refresh();render();};
actions['start-song']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);const related=state.productions.find(p=>!p.cancelled&&canonicalKey(songOf(p))===canonicalKey(s));let previous;if(related){if(!confirm('Há uma produção da mesma música ou de uma versão semelhante. Criar explicitamente uma nova versão vinculada, preservando o histórico?'))return;previous=related;}const p=await createProduction(s.id,previous);route('production',p.id);};
actions['open-production']=b=>route('production',b.dataset.id);
actions['create-selected']=async()=>{if(!state.selected.size)throw Error('Selecione pelo menos uma música.');for(const id of state.selected)await createProduction(id);await refresh();signal();route('production');toast('Produções individuais iniciadas.');};
actions['suggest-five']=async()=>{await refresh();const count=Math.max(0,Number(settings().dailyProduction)-state.selected.size);const candidates=state.songs.filter(s=>!(state.reservations||[]).some(r=>r.id===canonicalKey(s)&&r.status!=='cancelled')&&!state.productions.some(p=>p.songId===s.id&&!p.cancelled));const unique=new Map(candidates.map(s=>[canonicalKey(s),s]));const chosen=[...unique.values()].sort(()=>Math.random()-.5).slice(0,count);const added=await reserveSongs(chosen);await refresh();signal();render();toast(`${added} músicas inéditas reservadas. A playlist está salva.`);};
actions['unselect-song']=async b=>{await releaseSong(state.songs.find(s=>s.id===b.dataset.id));await refresh();signal();render();};
actions['prev-page']=()=>{state.page=Math.max(0,state.page-1);render();};actions['next-page']=()=>{if((state.page+1)*30<filteredSongs().length)state.page++;render();};
actions['manual-song']=()=>{showDialog(`<h2>Adicionar música real</h2><form id="song-form">${input('title','Título','','text','required')}${input('artist','Artista','','text','required')}${input('year','Ano da gravação (conferir fonte)','','number','min="1960" max="2009" required')}${input('genre','Gênero')}${input('album','Álbum verificado')}${input('versionName','Versão / gravação')}${input('country','País de origem, se verificado')}${input('source','URL da fonte','','url')}<button type="submit">Cadastrar música</button></form>`);$('#song-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const s=Object.fromEntries(new FormData(e.target));const result=await importSongs([s]);if(!result.added)throw Error('Música já cadastrada (artista e título).');$('#dialog').close();await refresh();render();toast('Música cadastrada com curadoria pendente.');});};};
actions['sync-rankings']=async()=>{const response=await fetch('data/catalog.json');if(!response.ok)throw Error('Catálogo distribuído indisponível.');const data=await response.json();const {blob}=await exportBackup();download(blob,'GMM-backup-antes-rankings-'+today()+'.zip');const result=await mergeVerifiedRankings(data.songs);await refresh();signal();render();toast(result.addedMemberships+' vínculos atualizados; '+result.conflicts+' conflitos e '+result.missing+' gravações ausentes para revisão. Backup deste navegador iniciado; nenhum registro musical novo foi inserido.');};
actions['song-info']=b=>{const s=state.songs.find(s=>s.id===b.dataset.id);showDialog(`<h2>${esc(s.title)}</h2><p>${esc(s.artist)} · ${s.year} · ${s.decade}</p><p>${esc(s.yearMeaning||'Ano informado pelo operador; conferir fonte.')}</p><p>Gênero: ${esc(s.genre||'Não informado')} · País: ${esc(s.country||'Não informado')}</p><p>${safeURL(s.source)?`<a target="_blank" rel="noopener noreferrer" href="${esc(safeURL(s.source))}">Consultar fonte de metadados</a>`:'Sem referência de fonte'}</p><p>ID: ${esc(s.sourceId||s.id)}</p><p>Validação: ${s.validation==='curated'?'Revisão editorial concluída':'Revisão editorial pendente'}.</p>${btn('curate-song','Registrar revisão editorial','data-id="'+s.id+'"','secondary')} ${btn('legacy-use','Registrar uso anterior','data-id="'+s.id+'"','secondary')}${rankingDetails(s)}<h3>Histórico de uso</h3>${state.productions.filter(p=>canonicalKey(songOf(p))===canonicalKey(s)).map(p=>`<p>V${p.version} · ${p.cancelled?'Cancelada':STATUS[p.status]} · ${p.createdAt.slice(0,10)}</p>`).join('')||'<p>Sem produção anterior.</p>'}<p><small>Marque somente após conferir título, artista, versão e ano na fonte.</small></p>`);};
actions['legacy-use']=b=>{const song=state.songs.find(s=>s.id===b.dataset.id);showDialog(`<h2>Registrar uso anterior</h2><p>${esc(song.title)} — ${esc(song.artist)}</p><form id="legacy-form">${input('legacy-date','Data efetiva',today(),'date','required')}${select('legacy-platform','Uso anterior',{produced:'Produzida (sem publicação)',tiktok:'Publicada no TikTok',youtube:'Publicada no YouTube'},'produced')}${input('legacy-url','Link da publicação, se houver','','url')}<p class="muted">Este registro impede a sugestão como inédita. Não cria um vídeo.</p><button type="submit">Registrar histórico</button></form>`);$('#legacy-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const platform=$('#legacy-platform').value,url=$('#legacy-url').value,date=$('#legacy-date').value;if(platform!=='produced'&&!safeURL(url))throw Error('Informe o link da publicação anterior.');if(url&&state.publications.some(pub=>pub.url===url))throw Error('Link já registrado.');const p=await createProduction(song.id);p.historical=true;p.createdAt=date+'T12:00:00.000Z';p.status=platform==='produced'?4:6;await put('productions',p);if(platform!=='produced')await put('publications',{id:uid(),productionId:p.id,platform,status:'published',title:song.title+' — '+song.artist,url,publishedAt:date+'T12:00',historical:true,metrics:{},createdAt:now()});await audit('legacy_use_registered',p.id);$('#dialog').close();await refresh();render();toast('Uso anterior registrado e repertório reservado.');});};};
actions['curate-song']=async b=>{const s=state.songs.find(s=>s.id===b.dataset.id);if(!safeURL(s.source))throw Error('Inclua uma fonte verificável antes de concluir a curadoria.');if(!confirm('Você conferiu título, artista, versão e ano na fonte?'))return;s.validation='curated';s.reviewedAt=now();await put('songs',s);await audit('song_reviewed',s.id);$('#dialog').close();await refresh();render();};
actions['import-songs']=()=>{showDialog(`<h2>Importar catálogo</h2><p>Selecione JSON com uma lista de músicas (ou objeto com songs), ou CSV UTF-8 com cabeçalho: title,artist,year,genre,country,source. Todos os registros são validados antes de gravar.</p><input type="file" id="song-import" aria-label="Importar músicas JSON ou CSV" accept=".json,.csv"><p id="import-feedback"></p><details><summary>Exemplo de JSON</summary><pre class="code">[{"title":"Título real","artist":"Artista real","year":1985,"source":"https://fonte"}]</pre></details>`);$('#song-import').onchange=e=>guarded(async()=>{const f=e.target.files[0];if(!f)return;let rows;if(f.name.endsWith('.json')){const d=JSON.parse(await f.text());rows=Array.isArray(d)?d:d.songs;}else rows=parseCSV(await f.text());if(!Array.isArray(rows))throw Error('Arquivo sem lista de músicas.');const ambiguous=rows.filter(row=>state.songs.some(old=>canonicalKey(old)===canonicalKey(row)&&(old.year!==Number(row.year)||(old.sourceId&&row.sourceId&&old.sourceId!==row.sourceId))));if(ambiguous.length&&!confirm(`${ambiguous.length} registros podem ser versões ou cadastros semelhantes. Manter separados para revisão editorial?`))return;const r=await importSongs(rows);$('#import-feedback').textContent=`${r.added} cadastradas; ${r.duplicates} duplicadas ignoradas.`;await refresh();});};
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('CSV com aspas não fechadas.');if(field||row.length){row.push(field);rows.push(row);}const headers=(rows.shift()||[]).map(s=>s.replace(/^\uFEFF/,'').trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}
actions['save-production']=async()=>{await saveProduction();toast('Produção salva.');};
actions['approve-review']=async b=>{if(uploading)throw Error('Aguarde o término da importação antes da revisão.');const p=state.productions.find(p=>p.id===b.dataset.id),files=assetsOf(p.id),finals=files.filter(a=>['tiktok','youtube'].includes(a.role));if(!files.some(a=>a.role==='cover')||!finals.length)throw Error('Associe uma capa e pelo menos um vídeo final antes da revisão.');if(!confirm('Você assistiu ao vídeo e conferiu capa e textos? Registrar revisão editorial?'))return;p.approval={at:now(),rightsConfirmed:rightsIssues(p).length===0,files:finals.map(a=>({id:a.id,hash:a.hash}))};await put('productions',p);await audit('editorial_review_approved',p.id);toast('Revisão registrada. Novos arquivos exigem nova revisão.');};
function rightsIssues(p,platform){const issues=[];if(p.licenseUntil&&p.licenseUntil<today())issues.push('A licença informada está vencida.');for(const [k,v]of Object.entries(p.rights||{})){if(platform&&['tiktok','youtube'].includes(k)&&k!==platform)continue;if(['pending','unauthorized','expired'].includes(v))issues.push(`${{recording:'Gravação',composition:'Composição',visual:'Imagens',tiktok:'TikTok',youtube:'YouTube',commercial:'Uso comercial'}[k]}: ${RIGHTS[v]}.`);}return issues;}
