async function publicationDialog(pid,platform,existing,chosenDestination,serviceMedia){const targetId=chosenDestination||destinationOf(existing||{platform}),target=POST_DESTINATIONS[targetId];if(!target||target.platform!==platform)throw Error('Plataforma/formato inválido.');await refresh();const p=state.productions.find(p=>p.id===pid);if(!p){showDialog('<h2>Produção indisponível</h2><p>Reabra uma produção antes de preparar a postagem.</p>');return;}const s=songOf(p)||{},saved=existing?state.publications.find(q=>q.id===existing.id):state.publications.find(q=>q.productionId===pid&&q.platform===platform&&destinationOf(q)===targetId&&['draft','planned'].includes(q.status)),base=saved||{id:uid(),productionId:pid,platform,destination:targetId,status:'draft',metrics:{}},ctx=prepareEditorial(s,p,base),pub=saved||{...base,title:ctx.suggestion.title,description:ctx.suggestion.description,hashtags:ctx.suggestion.hashtags};if(pub.serviceMediaId&&!serviceMedia){try{const result=await api('/library?includeTrashed=1');serviceMedia=result.media.find(m=>m.id===pub.serviceMediaId);}catch{}}let localRenders=[];try{localRenders=(await assemblyPackageAssets(pid,{includeTrashed:!!saved})).filter(a=>!a.trashedAt||a.id===pub.localRenderAssetId);}catch{}const finals=[...(serviceMedia?[{id:'media:'+serviceMedia.id,originalName:serviceMedia.name+(serviceMedia.trashedAt?' (na lixeira; referência histórica)':''),name:serviceMedia.name,hash:serviceMedia.hash,version:serviceMedia.productionVersion||1,serviceRender:true,serviceMediaId:serviceMedia.id,url:'/api/library/'+serviceMedia.id+'/file'}]:[]),...assetsOf(pid).filter(a=>finalRoleAllowed(a.role,platform)&&renderCompatible(a,targetId)),...localRenders.filter(a=>(finalRoleAllowed(a.role,platform)||platform==='youtube'&&targetId==='shorts')&&renderCompatible(a,targetId)).map(a=>({...a,id:'render:'+a.id,originalName:a.name,version:a.version,serviceRender:true}))];if(pub.localRenderAssetId&&!finals.some(a=>a.id==='render:'+pub.localRenderAssetId))finals.push({id:'render:'+pub.localRenderAssetId,jobId:pub.localRenderJobId,serviceRender:true,unavailable:true,originalName:'MP4 associado — prévia indisponível no serviço',version:p.version});showDialog(`<h2>${esc(target.label)} · V${p.version}</h2><form id="publication-form"><section id="posting-guard" class="note"></section><p class="muted">${esc(target.note)}</p>${editorialControls(ctx,esc)}${input('pubTitle','Título',pub.title,'text','required')}${select('finalAssetId','Vídeo final desta plataforma',{'':'Selecionar arquivo',...Object.fromEntries(finals.map(a=>[a.id,a.originalName+' · V'+a.version]))},pub.serviceMediaId?'media:'+pub.serviceMediaId:pub.localRenderAssetId?'render:'+pub.localRenderAssetId:serviceMedia?'media:'+serviceMedia.id:pub.finalAssetId)}<label class="field">Descrição<textarea id="pubDescription">${esc(pub.description)}</textarea></label>${input('hashtags','Hashtags',pub.hashtags)}${publicationOptions(pub)}<div id="publication-video"></div>${editorialCopyControls(platform)}<div class="form-grid">${input('plannedAt','Data planejada (no fuso escolhido nas opções)',pub.plannedAt||'','datetime-local')}${input('publishedAt','Data efetiva (horário deste computador)',Number.isFinite(Date.parse(pub.publishedAt))?new Date(Date.parse(pub.publishedAt)-new Date(pub.publishedAt).getTimezoneOffset()*60000).toISOString().slice(0,16):'','datetime-local')}${select('pubStatus','Situação',{draft:'Rascunho',planned:'Planejada (manual)',published:'Publicada',archived:'Arquivada'},pub.status)}${input('pubURL','Link da publicação',pub.url||'','url')}</div><details><summary>Métricas manuais</summary><div class="form-grid">${['views','likes','comments','shares'].map((k,i)=>input('metric-'+k,['Visualizações','Curtidas','Comentários','Compartilhamentos'][i],pub.metrics?.[k]||0,'number','min="0"')).join('')}</div></details><p class="notice">Salvar não publica nem agenda na plataforma. </p>${pub.url&&pub.publishedAt?input('correctionReason','Motivo da correção', '', 'text'):''}<button type="submit">Salvar registro</button></form>`);const editor=bindEditorial($('#dialog-body'),{song:s,production:p,pub,context:ctx,esc});const previewFinal=()=>{const a=finals.find(a=>a.id===$('#finalAssetId').value),link=$('#post-download'),url=a&&!a.unavailable?(a.serviceRender?a.url:mediaURL(a)):'';link.hidden=!url;if(url){link.href=a.serviceRender?url+'?download=1':url;link.download=a.originalName||a.name;}else{link.removeAttribute('href');link.removeAttribute('download');}$('#publication-video').innerHTML=a?.unavailable?'<p class="muted">O vínculo com o MP4 anterior será preservado. Serviço indisponível para prévia.</p>':a?`<video controls preload="metadata" src="${a.serviceRender?esc(a.url):mediaURL(a)}" aria-label="Prévia do vídeo final"></video><p id="destination-measurement" class="muted"></p>`:'';const video=$('#publication-video video');if(video)video.onloadedmetadata=()=>{const mismatch=(target.format==='16:9'&&video.videoWidth<video.videoHeight)||(target.format==='9:16'&&video.videoWidth>video.videoHeight);$('#destination-measurement').textContent=`MP4: ${video.videoWidth}×${video.videoHeight} · ${video.duration.toFixed(1)} s. ${mismatch?'Enquadramento diferente do preset; arquivo mantido sem recorte. Confira o formato antes de postar.':''} ${destinationIssues(targetId,{duration:video.duration,width:video.videoWidth,height:video.videoHeight}).join(' ')}`;};};const guard=await mountPostingGuard($('#dialog-body'),{song:s,production:p,pub,hash:()=>finals.find(a=>a.id===$('#finalAssetId').value)?.hash||null});$('#finalAssetId').onchange=()=>{previewFinal();guard.refresh();};previewFinal();$('#publication-form').onsubmit=e=>{e.preventDefault();guarded(async()=>{const checks=editor.checks();const video=$('#publication-video video');if(video&&video.readyState>=1){checks.errors.push(...destinationIssues(targetId,{duration:video.duration,width:video.videoWidth,height:video.videoHeight}));}else if($('#finalAssetId').value&&['shorts','instagram'].includes(targetId))checks.errors.push('Aguarde a medição do MP4 para conferir duração e enquadramento deste preset.');if(checks.errors.length)throw Error(checks.errors.join(' '));const confirmedFacts=editor.facts(),selectedFinal=finals.find(a=>a.id===$('#finalAssetId').value);const next={...pub,...guard.fields({requireDecision:$('#pubStatus').value==='published'&&!saved}),correctionReason:$('#correctionReason')?.value||'',destination:targetId,title:$('#pubTitle').value,description:$('#pubDescription').value,hashtags:$('#hashtags').value,plannedAt:$('#plannedAt').value,publishedAt:$('#publishedAt').value,status:$('#pubStatus').value,url:$('#pubURL').value,finalAssetId:selectedFinal?.serviceRender?'':$('#finalAssetId').value,localRenderAssetId:selectedFinal?.serviceRender&&!selectedFinal.serviceMediaId?selectedFinal.id.slice(7):null,serviceMediaId:selectedFinal?.serviceMediaId||null,localRenderJobId:selectedFinal?.serviceRender?selectedFinal.jobId:null,options:readPublicationOptions(platform,pub.options),editorial:editor.metadata(),updatedAt:now(),metrics:Object.fromEntries(['views','likes','comments','shares'].map(k=>[k,Math.max(0,Number($('#metric-'+k).value)||0)]))};if(next.url&&!safeURL(next.url))throw Error('Informe um link http ou https válido.');if(next.status==='published'&&(!next.url||!next.publishedAt||!next.finalAssetId&&!next.localRenderAssetId&&!next.serviceMediaId))throw Error('Para registrar como publicada, informe vídeo final, data efetiva e URL.');if(next.url&&state.publications.some(x=>x.id!==next.id&&x.url===next.url))throw Error('Este link já está registrado em outra publicação.');await saveEditorialPublication(next,saved,confirmedFacts,p);let historySync=true;if(['youtube','tiktok'].includes(platform)&&['published','archived'].includes(next.status)&&next.url&&next.publishedAt){try{await api('/operations/records',{method:'POST',data:{productions:[{...p,title:s.title,artist:s.artist,decade:s.decade}],publications:[next],accounts:(await all('settings')).find(s=>s.id==='postingAccounts')?.accounts||[]}});}catch{historySync=false;}}$('#dialog').close();await refresh();render();toast(historySync?'Registro salvo. Nenhum envio automático foi realizado.':'Registro salvo no navegador; sincronização do histórico com serviço pendente. Nenhum envio externo.');});};}
