async function init(){mountVersion();await initializeService();await refresh();if(!state.settings.some(s=>s.id==='catalogSeed')){try{const r=await fetch('data/catalog.json');if(!r.ok)throw Error('Catálogo indisponível');const catalog=await r.json();await importSongs(catalog.songs);await put('settings',{id:'catalogSeed',at:now(),count:catalog.count,notes:catalog.notes});}catch(e){toast('Não foi possível carregar o catálogo. Você pode importar registros reais.');}}await refresh();const restoredFilters=state.settings.find(s=>s.id==='catalogRankingFilter');if(restoredFilters){state.filters={...state.filters,rankingList:restoredFilters.rankingList||'',rankingLimit:restoredFilters.rankingLimit||'30'};state.decade=restoredFilters.decade||'';state.sort=restoredFilters.sort||'relevance';}state.selected=new Set((state.reservations||[]).filter(r=>r.status==='reserved').map(r=>r.songId));const [view,id]=location.hash.slice(1).split('/');state.view=view in TITLES?view:'dashboard';state.active=id||null;await render();if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
if(channel)channel.onmessage=()=>{guarded(async()=>{await refresh();if(['catalog','dashboard','production','publications','archive'].includes(state.view)&&!state.active)render();});};
init().catch(e=>{$('#store-status').textContent='Armazenamento indisponível';$('#main').textContent='Não foi possível abrir o banco local. Use uma janela normal do navegador com armazenamento habilitado. '+e.message;});

async function selectTemplate(id){clearTimeout(coverTimer);readCover();state.cover={...state.cover,...templatePreset(id)};delete state.cover.backgroundAssetId;state.bg=null;await saveCoverDraft();await render();}
actions['select-template']=b=>selectTemplate(b.dataset.id);

let searchTimer;
async function rememberSearch(){const q=state.search.trim();if(!q)return;const old=state.settings.find(s=>s.id==='searchHistory')?.queries||[];const record={id:'searchHistory',queries:[q,...old.filter(v=>v!==q)].slice(0,8)};await put('settings',record);state.settings=state.settings.filter(s=>s.id!==record.id).concat(record);}
function bindCatalog(){const search=$('#catalog-search');if(!search)return;
 search.oninput=()=>{state.search=search.value;state.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>guarded(async()=>{const pos=search.selectionStart;await render();const current=$('#catalog-search');if(current){current.focus();try{current.setSelectionRange(pos,pos);}catch{}}}),180);};
 search.onchange=()=>guarded(rememberSearch);search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(searchTimer);guarded(async()=>{state.search=search.value;await rememberSearch();await render();$('#catalog-search')?.focus();});}};
 $('#advanced-filters').ontoggle=e=>{if(e.target.isConnected)state.advanced=e.target.open;};
 for(const el of document.querySelectorAll('[id^="filter-"]'))el.onchange=()=>{const key=el.id.slice(7);if(state.filters[key]===el.value)return;clearTimeout(searchTimer);state.filters[key]=el.value;state.page=0;render();};
}
actions['clear-filters']=async()=>{await put('settings',{id:'catalogRankingFilter',rankingList:'',rankingLimit:'30',decade:'',sort:state.sort});clearTimeout(searchTimer);Object.assign(state,{search:'',decade:'',repertoire:'',favorites:false,unused:false,filters:{},page:0});render();};
actions['recent-search']=b=>{state.search=b.dataset.query;state.page=0;render();};
actions['metadata-search']=()=>showDialog(`<h2>Consultar metadados</h2><p>Pesquise a gravação na fonte e confira artista, versão e ano antes de cadastrar. Esta consulta abre o MusicBrainz; o catálogo local continua disponível offline.</p><a href="${esc(musicBrainzSearchURL(state.search))}" target="_blank" rel="noopener noreferrer">Abrir pesquisa no MusicBrainz</a><p class="muted">A fonte fornece metadados. Não autoriza o download da música. A consulta automática ainda depende da configuração de uso do serviço.</p>`);
actions['trash-cover']=b=>{const a=state.assets.find(a=>a.id===b.dataset.id);if(!a||a.role!=='cover'||a.trashedAt)throw Error('Capa indisponível.');const linked=state.assets.filter(x=>x.coverConfig?.backgroundAssetId===a.id).length;showDialog(`<h2>Excluir capa para a lixeira?</h2><p>${esc(a.name)} · V${a.version}<br>ID: ${esc(a.id)}</p><p>Somente esta capa deste navegador sairá das novas seleções. Bytes, ID, referências e renders/publicações anteriores serão preservados. Não apaga MP4, fonte nem arquivo em pasta Windows, e não libera espaço.</p><p>${linked} outra(s) arte(s) usam esta capa como fundo. Presets e renders do serviço podem ter referências/cópias próprias; não serão modificados.</p><label><input type="checkbox" id="cover-trash-ack"> Entendi o alvo e a preservação dos vínculos existentes.</label><button id="cover-trash-confirm">Excluir capa (recuperável)</button>`);$('#cover-trash-confirm').onclick=()=>guarded(async()=>{if(!$('#cover-trash-ack').checked)throw Error('Confira o alvo e confirme a preservação dos vínculos.');await changeCoverTrash(a.id,{productionId:a.productionId,hash:a.hash});$('#dialog').close();await refresh();render();toast('Capa na lixeira recuperável; bytes e histórico preservados.');});};
actions['restore-cover']=async b=>{const a=state.assets.find(a=>a.id===b.dataset.id);if(!a||a.role!=='cover')throw Error('Capa indisponível.');await changeCoverTrash(a.id,{productionId:a.productionId,hash:a.hash,restore:true});await refresh();render();toast('Capa restaurada com o mesmo ID.');};
actions['recover-cover']=async b=>{const a=state.assets.find(a=>a.id===b.dataset.id);if(!a?.coverConfig)return;state.cover={...a.coverConfig};state.coverProd=a.productionId;state.bg=null;await saveCoverDraft();await route('covers');};
function publicationOptions(pub){const o=pub.options||{};if(!['youtube','tiktok'].includes(pub.platform))return `<p class="muted">Registro manual neste navegador · ${esc(PLATFORMS[pub.platform])}. Fora da rotina automática do serviço. Confirme privacidade, direitos e recursos na plataforma.</p>${input('pubTimeZone','Fuso da publicação',o.timeZone||'America/Sao_Paulo')}${select('pubAudioReady','Áudio do arquivo final',{pending:'Conferir áudio',ready:'MP4 completo com áudio'},o.audioReady?'ready':'pending')}<label class="field">${pub.platform==='odysee'?'Tags/categorias Odysee (sem #, conferir na plataforma)':pub.platform==='rumble'?'Licença/visibilidade a conferir no Rumble':'Audiência/legenda a conferir na plataforma'}<textarea id="pubManualNote">${esc(o.manualNote||'')}</textarea></label>`;return `<div class="form-grid">${select('pubTimeZone','Fuso da publicação',{'America/Sao_Paulo':'Brasília / São Paulo','UTC':'UTC','America/New_York':'Nova York','Europe/Lisbon':'Lisboa'},o.timeZone||'America/Sao_Paulo')}${select('pubAudioReady','Áudio do arquivo final',{pending:'Ainda precisa de áudio no aplicativo',ready:'MP4 completo com áudio'},o.audioReady?'ready':'pending')}</div><details class="publication-options"><summary>Opções do ${pub.platform==='youtube'?'YouTube':'TikTok'}</summary><div class="form-grid">${select('pubPrivacy','Privacidade (preparação)',pub.platform==='youtube'?{private:'Privado',unlisted:'Não listado',public:'Público'}:{'':'Escolher quando conectar',SELF_ONLY:'Somente eu'},o.privacy||'private')}${pub.platform==='youtube'?input('pubCategory','Categoria (YouTube)',o.categoryId||'10')+input('pubTags','Tags separadas por vírgula',(o.tags||[]).join(', ')):''}</div>${pub.platform==='youtube'?`<label><input type="checkbox" id="pubKids" ${o.madeForKids?'checked':''}> Conteúdo destinado a crianças</label><br><label><input type="checkbox" id="pubSynthetic" ${o.containsSyntheticMedia?'checked':''}> Conteúdo alterado ou sintético a declarar</label>`:`${[['allowComment','Permitir comentários'],['allowDuet','Permitir Dueto'],['allowStitch','Permitir Costura'],['commercialContent','Conteúdo comercial']].map(([id,label])=>`<label><input type="checkbox" id="pub-${id}" ${o[id]?'checked':''}> ${label}</label><br>`).join('')}`}<small>Opções preparadas localmente. Disponibilidade e permissões deverão ser confirmadas pela plataforma conectada.</small></details>`;}
function readPublicationOptions(platform,previous={}){const common={...previous,timeZone:$('#pubTimeZone').value,audioReady:$('#pubAudioReady').value==='ready'};if(!['youtube','tiktok'].includes(platform))return {...common,manualNote:$('#pubManualNote').value};return platform==='youtube'?{...common,privacy:$('#pubPrivacy').value,categoryId:$('#pubCategory').value,tags:$('#pubTags').value.split(',').map(s=>s.trim()).filter(Boolean),madeForKids:$('#pubKids').checked,containsSyntheticMedia:$('#pubSynthetic').checked}:{...common,privacy:$('#pubPrivacy').value,...Object.fromEntries(['allowComment','allowDuet','allowStitch','commercialContent'].map(k=>[k,$('#pub-'+k).checked]))};}
function deliveryPanel(pubs){return `<details class="panel delivery-panel"><summary>Preparação de envio e testes locais</summary><p class="muted">Contas desconectadas · envio real desabilitado. Simulações não publicam nem alteram métricas.</p>${pubs.map(pub=>`<article class="delivery-item"><div><b>${esc(pub.title)}</b><small>${esc(POST_DESTINATIONS[destinationOf(pub)]?.label||pub.platform)} · ${esc(deliveryLabel(pub))}</small>${pub.delivery?.envelope?.account?`<small>Destino de teste: ${esc(pub.delivery.envelope.account.label||pub.delivery.envelope.account.id||'Simulado')}</small>`:''}${pub.delivery?.issues?.length?`<ul>${[...new Set(pub.delivery.issues.map(i=>/licença|direitos/i.test(i)?'Envio pelo serviço indisponível nesta configuração. O registro local pode ser salvo.':i))].map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`:''}${pub.delivery?.error?`<p role="status">${esc(pub.delivery.error.message||pub.delivery.error)}</p>`:''}</div><div class="actions">${btn('prepare-delivery','Conferir preparação',`data-id="${pub.id}"`,'secondary small')}${btn('simulate-delivery','Testar simulação',`data-id="${pub.id}"`,'secondary small')}${pub.delivery?btn('cancel-delivery','Cancelar teste',`data-id="${pub.id}"`,'link small'):''}${btn('open-production','Abrir produção',`data-id="${pub.productionId}"`,'link small')}${btn('export-production','Pacote manual',`data-id="${pub.productionId}"`,'link small')}</div></article>`).join('')||'<p>Prepare uma publicação dentro de uma produção para conferir seu envio.</p>'}</details>`;}
actions['prepare-delivery']=async b=>{const pub=state.publications.find(p=>p.id===b.dataset.id);await prepareDelivery(pub,state.productions.find(p=>p.id===pub.productionId),assetsOf(pub.productionId));await refresh();await render();$('.delivery-panel').open=true;};
actions['simulate-delivery']=b=>{const pub=state.publications.find(p=>p.id===b.dataset.id);showDialog(`<h2>Simulação de ${pub.platform==='youtube'?'YouTube':'TikTok'}</h2><p>Conta de teste local. Nenhum arquivo será enviado a uma plataforma.</p>${select('simulation-scenario','Cenário',{success:'Envio concluído',network:'Falha de conexão (permite repetir)',rejected:'Rejeição do provedor',revoked:'Permissão revogada'},'success')}<button id="run-simulation">Aprovar e executar teste</button>`);$('#run-simulation').onclick=()=>guarded(async()=>{const scenario=$('#simulation-scenario').value;let current=state.publications.find(p=>p.id===pub.id);if(!(current.delivery?.state==='failed'&&current.delivery?.error?.retryable)){current=await prepareDelivery(current,state.productions.find(p=>p.id===pub.productionId),assetsOf(pub.productionId),{id:'simulation:'+pub.platform,platform:pub.platform,mode:'simulation',label:'Conta de teste local'});}if(current.delivery.state==='simulation_ready'||current.delivery.state==='failed')await runSimulation(current,scenario);$('#dialog').close();await refresh();await render();$('.delivery-panel').open=true;toast('Resultado do teste registrado separadamente da publicação manual.');});};
actions['cancel-delivery']=async b=>{await cancelDelivery(state.publications.find(p=>p.id===b.dataset.id));await refresh();await render();$('.delivery-panel').open=true;};



async function saveCoverDraft(){if(!state.cover)return;const config={...state.cover},productionId=state.coverProd||'';const record={config,productionId,updatedAt:now()};const changes=[{store:'settings',value:{...record,id:'coverDraft'}},{store:'settings',value:{...record,id:'coverDraft:'+(productionId||'standalone')}}];await batch(changes);for(const c of changes)state.settings=state.settings.filter(v=>v.id!==c.value.id).concat(c.value);}
async function openProductionCover(pid){if(!pid)return;if(state.view==='covers'){clearTimeout(coverTimer);await saveCoverDraft();}const p=state.productions.find(p=>p.id===pid),s=songOf(p);const draft=state.settings.find(d=>d.id==='coverDraft:'+pid)||state.settings.find(d=>d.id==='coverDraft'&&d.productionId===pid);const previous=assetsOf(pid).filter(a=>a.role==='cover'&&a.coverConfig).at(-1);state.coverProd=pid;state.cover={title:s.title,artist:s.artist,year:p.versionYear||s.year,style:'cassette',format:'vertical',font:104,x:.085,y:.23,text:'#f8f0df',accent:'#edc283',...(draft?.config||previous?.coverConfig)};state.bg=null;await saveCoverDraft();await route('covers');}
